import {animationIKTypes,animationIKSpaces} from './animation-ik.js';
export function renderAnimationIK(editor,node,base){
  if(!animationIKTypes.includes(node.type))return '';
  const p=node.properties,world=editor.hooks.world(),bones=new Set();world.groups.get(editor.previewTarget||world.selected)?.traverse(o=>{if(o.isBone)bones.add(o.name);});
  const bone=(label,key)=>editor.input(label,base+'.'+key,p[key],'text',bones.size?[['','없음'],...[...new Set([...bones,p[key]])].filter(Boolean).map(b=>[b,b])]:undefined),input=(label,key,type='number',choices,step='.05')=>editor.input(label,base+'.'+key,p[key],type,choices,step),vector=(label,key)=>'<fieldset class="anim-ik-vector"><legend>'+label+'</legend>'+['X','Y','Z'].map((axis,i)=>editor.input(axis,base+'.'+key+'.'+i,p[key][i],'number')).join('')+'</fieldset>',section=(key,label,body)=>'<details data-sync-section="ik-'+key+'"><summary>'+label+'</summary>'+body+'</details>',spaces=animationIKSpaces.map(s=>[s,{component:'컴포넌트',world:'월드',bone:'뼈',parentBone:'부모 뼈'}[s]]),actors=key=>[['','좌표 직접 지정'],...world.objects.filter(o=>o.kind!=='component').map(o=>[o.id,o.name]),...p[key]&&!world.objects.some(o=>o.id===p[key])?[[p[key],p[key]]]:[]];
  if(node.type==='fullBodyIK')return bone('루트 뼈','root')+editor.input('루트 동작',base+'.rootBehavior',p.rootBehavior||'fixed','text',[['fixed','위치 유지'],['pin','입력 포즈 고정'],['prePull','먼저 당기기'],['free','자유 이동']])+editor.input('루트 당김',base+'.rootPull',p.rootPull??1,'number')+editor.input('최대 루트 이동',base+'.rootMaxDistance',p.rootMaxDistance??100000,'number')+editor.input('늘이기 허용',base+'.allowStretch',p.allowStretch??false,'checkbox')+((p.allowStretch??false)?editor.input('최대 길이 배율',base+'.maxStretch',p.maxStretch??1.5,'number'):'')+'<details data-sync-section="fbik-bones"><summary>뼈 설정</summary><button data-anim-act="fbik-bone-add">뼈 설정 추가</button>'+(p.boneSettings||[]).map((v,i)=>'<section>'+editor.input('뼈',base+'.boneSettings.'+i+'.bone',v.bone,'text',bones.size?[...bones].map(b=>[b,b]):undefined)+editor.input('회전 강성',base+'.boneSettings.'+i+'.rotationStiffness',v.rotationStiffness||0,'number')+(v.bone===p.root||p.allowStretch?editor.input(v.bone===p.root?'루트 위치 강성':'늘이기 위치 강성',base+'.boneSettings.'+i+'.positionStiffness',v.positionStiffness||0,'number'):'')+['X','Y','Z'].map((axis,j)=>editor.input('선호 회전 '+axis+' · °',base+'.boneSettings.'+i+'.preferredAngle.'+j,(v.preferredAngle||[0,0,0])[j],'number')).join('')+'<button data-anim-act="fbik-bone-remove" data-anim-index="'+i+'">설정 삭제</button></section>').join('')+'</details>'+editor.parameter('가중치 파라미터',base+'.parameter',p.parameter)+input('Alpha','alpha')+input('Alpha 배율','alphaScale')+input('Alpha 바이어스','alphaBias')+input('허용 오차','precision')+input('최대 반복','iterations','number',undefined,'1')+input('디버그 표시','debug','checkbox')+'<output data-anim-ik-runtime role="status"></output><button data-anim-act="fbik-add">목표 추가</button>'+p.effectors.map((e,i)=>'<details open><summary>'+String(e.id).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))+'</summary>'+editor.input('목표 ID',base+'.effectors.'+i+'.id',e.id)+editor.input('끝 뼈',base+'.effectors.'+i+'.bone',e.bone,'text',bones.size?[...bones].map(b=>[b,b]):undefined)+editor.input('목표 오브젝트',base+'.effectors.'+i+'.targetActor',e.targetActor,'text',[['','좌표 직접 지정'],...world.objects.map(o=>[o.id,o.name])])+editor.input('공간',base+'.effectors.'+i+'.space',e.space,'text',[['component','컴포넌트'],['world','월드']])+['X','Y','Z'].map((axis,j)=>editor.input(axis,base+'.effectors.'+i+'.target.'+j,e.target[j],'number')).join('')+editor.input('위치 가중치',base+'.effectors.'+i+'.weight',e.weight,'number')+['X','Y','Z'].map((axis,j)=>editor.input('회전 '+axis+' · °',base+'.effectors.'+i+'.rotation.'+j,(e.rotation||[0,0,0])[j],'number')).join('')+editor.input('회전 가중치',base+'.effectors.'+i+'.rotationWeight',e.rotationWeight||0,'number')+'<output data-anim-goal-runtime="'+i+'" role="status"></output><button data-anim-act="fbik-remove" data-anim-index="'+i+'">목표 삭제</button></details>').join('')+editor.input('제외 뼈 · JSON',base+'.excludedBones',p.excludedBones,'json')+editor.input('관절 제한 · JSON',base+'.jointLimits',p.jointLimits,'json');
  let html=bone('루트 뼈','root')+bone('끝 뼈','tip')+editor.parameter('가중치 파라미터',base+'.parameter',p.parameter)+input('Alpha','alpha')+input('Alpha 배율','alphaScale')+input('Alpha 바이어스','alphaBias')+input('디버그 표시','debug','checkbox')+'<output data-anim-ik-runtime role="status"></output>';
  html+=section('target','목표',input('좌표 공간','space','text',spaces)+(['bone','parentBone'].includes(p.space)?bone('기준 뼈','spaceBone'):'')+input('목표 오브젝트','targetActor','text',actors('targetActor'))+vector('목표 위치','target')+input('위치 가중치','positionWeight')+input('초기 위치 차이 유지','maintainPositionOffset','checkbox'));
  html+=section('rotation','끝 뼈 회전',input('회전 처리','rotationMode','text',[['local','로컬 회전 유지'],['component','컴포넌트 회전 유지'],['target','목표 회전']])+vector('목표 회전 · °','rotation')+input('회전 가중치','rotationWeight')+input('초기 회전 차이 유지','maintainRotationOffset','checkbox'));
  if(node.type==='twoBoneIK')html+=section('hint','관절 힌트',input('힌트 공간','hintSpace','text',spaces)+(['bone','parentBone'].includes(p.hintSpace)?bone('힌트 기준 뼈','hintBone'):'')+input('힌트 오브젝트','hintActor','text',actors('hintActor'))+vector('힌트 위치','hint')+input('힌트 가중치','hintWeight'))+section('stretch','길이와 비틀림',input('늘이기 허용','allowStretch','checkbox')+input('늘이기 시작 비율','startStretch')+input('최대 늘이기 비율','maxStretch')+input('비틀림 허용','allowTwist','checkbox')+input('비틀림 축','twistAxis','text',[['x','X'],['y','Y'],['z','Z']]));
  else html+=section('solve','계산',input('목표 허용 오차','precision','number',undefined,'.001')+input('최대 반복','iterations','number',undefined,'1'));
  if(node.type==='ccdIK')html+=section('limits','관절 회전 제한',input('끝에서 시작','startFromTail','checkbox')+input('회전 제한 사용','enableRotationLimit','checkbox')+input('기본 회전각 · °','baseRotationLimit')+'<button data-anim-act="ik-limit-add">관절 추가</button>'+p.rotationLimits.map((v,i)=>'<section>'+editor.input('관절',base+'.rotationLimits.'+i+'.bone',v.bone,'text',bones.size?[...bones].map(b=>[b,b]):undefined)+editor.input('회전각 · °',base+'.rotationLimits.'+i+'.limit',v.limit,'number',undefined,'1')+'<button data-anim-act="ik-limit-remove" data-anim-index="'+i+'">삭제</button></section>').join(''));
  html+=section('joint-limits','기준 포즈 XYZ 제한','<button data-anim-act="ik-joint-add">관절 추가</button>'+(p.jointLimits||[]).map((v,i)=>'<section>'+editor.input('관절',base+'.jointLimits.'+i+'.bone',v.bone,'text',bones.size?[...bones].map(b=>[b,b]):undefined)+['minimum','maximum'].map(key=>'<fieldset class="anim-ik-vector"><legend>'+(key==='minimum'?'최소':'최대')+' · °</legend>'+['X','Y','Z'].map((axis,j)=>editor.input(axis,base+'.jointLimits.'+i+'.'+key+'.'+j,v[key][j],'number',undefined,'1')).join('')+'</fieldset>').join('')+'<button data-anim-act="ik-joint-remove" data-anim-index="'+i+'">삭제</button></section>').join(''));
  return html;
}
export function updateAnimationIKRuntime(editor,state){const out=editor.element.querySelector('[data-anim-ik-runtime]'),s=state?.ik?.find(s=>s.node===editor.selection),text=s?(s.missingActor?'목표 없음 · '+s.missingActor:'오차 '+s.error.toFixed(4)+' · '+s.iterations+'회 · '+Math.round(s.weight*100)+'%'):'';if(out&&out.textContent!==text)out.textContent=text;for(const field of editor.element.querySelectorAll('[data-anim-goal-runtime]')){const row=s?.effectors?.[Number(field.dataset.animGoalRuntime)],value=row?(row.missingActor?'목표 없음 · '+row.missingActor:'오차 '+row.error.toFixed(4)+' · '+Math.round(row.weight*100)+'%'):'';if(field.textContent!==value)field.textContent=value;}}
